using System; using System.IO; using System.Drawing; using System.Diagnostics; using System.Threading; using System.Windows.Forms; using System.Web.Script.Serialization; using System.Collections.Generic;
class App : Form {
 readonly string dir=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"UltraMegaTextSearchTool"); string source="";
 Label status=new Label(), metric=new Label(), buildtext=new Label(), guide=new Label(); ProgressBar progress=new ProgressBar(); TextBox query=new TextBox(), results=new TextBox(), filter=new TextBox(); List<string> matches=new List<string>(); Label filterCount=new Label(); CheckBox cs=new CheckBox(); Button build=new Button(), stop=new Button(), resume=new Button(), search=new Button(), cancel=new Button(), export=new Button(); System.Windows.Forms.Timer timer=new System.Windows.Forms.Timer(); Process worker, searching; JavaScriptSerializer json=new JavaScriptSerializer(); bool building=false,complete=false; Mutex mutex;
 App(){ Directory.CreateDirectory(dir); string sourceFile=Path.Combine(dir,"source-folder.txt"); if(File.Exists(sourceFile))source=File.ReadAllText(sourceFile); Text="Ultra Mega Text Search Tool"; ClientSize=new Size(920,710); MinimumSize=new Size(760,600); StartPosition=FormStartPosition.CenterScreen; BackColor=Color.FromArgb(245,247,251); Font=new Font("Segoe UI",10);
 var title=new Label{Text="Ultra Mega Text Search Tool",Font=new Font("Segoe UI",21,FontStyle.Bold),ForeColor=Color.FromArgb(25,45,77),AutoSize=true,Location=new Point(80,14)}; Controls.Add(title);
 var logo=new PictureBox{Image=Icon.ExtractAssociatedIcon(Application.ExecutablePath).ToBitmap(),SizeMode=PictureBoxSizeMode.Zoom}; logo.SetBounds(24,12,46,46); Controls.Add(logo);
