 stop.Text="Pause build"; stop.SetBounds(158,100,125,36); stop.Enabled=false; stop.Click+=(s,e)=>StopBuild(); Controls.Add(stop);
 resume.Text="Resume build"; resume.SetBounds(292,100,135,36); resume.Click+=(s,e)=>StartBuild(); Controls.Add(resume);
 buildtext.Text="Database status"; buildtext.SetBounds(445,105,440,25); buildtext.Anchor=AnchorStyles.Top|AnchorStyles.Left|AnchorStyles.Right; Controls.Add(buildtext);
 progress.SetBounds(24,146,865,20); progress.Anchor=AnchorStyles.Top|AnchorStyles.Left|AnchorStyles.Right; Controls.Add(progress);
 status.SetBounds(24,174,865,35); status.Anchor=AnchorStyles.Top|AnchorStyles.Left|AnchorStyles.Right; Controls.Add(status);
 var l=new Label{Text="Search text (at least 3 characters)",AutoSize=true,Location=new Point(24,216)}; Controls.Add(l);
 query.SetBounds(24,244,865,28); query.Anchor=AnchorStyles.Top|AnchorStyles.Left|AnchorStyles.Right; Controls.Add(query);
