 export.Text="Export results"; export.SetBounds(425,278,135,36); export.Enabled=false; export.Click+=(s,e)=>ExportResults(); Controls.Add(export);
 metric.SetBounds(24,325,865,26); Controls.Add(metric);
 Controls.Add(new Label{Text="Filter returned results:",AutoSize=true,Location=new Point(24,358)}); filter.SetBounds(190,354,300,28); filter.TextChanged+=(s,e)=>ApplyFilter(); Controls.Add(filter); filterCount.SetBounds(505,358,380,24); Controls.Add(filterCount);
 results.Multiline=true; results.ScrollBars=ScrollBars.Both; results.WordWrap=false; results.ReadOnly=true; results.Font=new Font("Consolas",10); results.SetBounds(24,392,865,263); results.Anchor=AnchorStyles.Top|AnchorStyles.Bottom|AnchorStyles.Left|AnchorStyles.Right; Controls.Add(results);
 var note=new Label{Text="Results may contain sensitive passwords. Everything stays on this computer.",ForeColor=Color.DimGray}; note.SetBounds(24,665,540,25); note.Anchor=AnchorStyles.Bottom|AnchorStyles.Left; Controls.Add(note);
 var credit=new LinkLabel{Text="Developed by treveansalt",AutoSize=true,LinkColor=Color.FromArgb(65,75,170)}; credit.SetBounds(540,665,190,25); credit.Anchor=AnchorStyles.Bottom|AnchorStyles.Right; credit.LinkClicked+=(s,e)=>{try{Process.Start("https://github.com/treveansalt/");}catch(Exception ex){MessageBox.Show(ex.Message,"Unable to open link");}}; Controls.Add(credit);
 var slop=new Label{Text="with added AI Slop",AutoSize=true,ForeColor=Color.DimGray,Location=new Point(730,665),Anchor=AnchorStyles.Bottom|AnchorStyles.Right}; Controls.Add(slop);
 timer.Interval=1000; timer.Tick+=(s,e)=>RefreshStatus(); timer.Start(); RefreshStatus(); FormClosing+=(s,e)=>{if(building){if(MessageBox.Show("Pause the build and close? Completed files are kept.","Breach Search",MessageBoxButtons.YesNo)!=DialogResult.Yes){e.Cancel=true;return;} StopBuild(); if(worker!=null)worker.WaitForExit();} if(searching!=null&&!searching.HasExited)searching.Kill();};
 }
 Process Run(string arg){string baseDir=AppDomain.CurrentDomain.BaseDirectory; string bundled=Path.Combine(baseDir,"python.exe"); string python=File.Exists(bundled)?bundled:"py.exe"; string prefix=File.Exists(bundled)?"":"-3 "; var p=new Process(); p.StartInfo=new ProcessStartInfo(python,prefix+"\""+Path.Combine(baseDir,"IndexedSearch.py")+"\" "+arg){UseShellExecute=false,CreateNoWindow=true,RedirectStandardError=true,RedirectStandardOutput=true,RedirectStandardInput=true,WorkingDirectory=baseDir}; p.StartInfo.EnvironmentVariables["ULTRA_MEGA_DB"]=dir; p.StartInfo.EnvironmentVariables["ULTRA_MEGA_SOURCE"]=source; try{p.Start();}catch(System.ComponentModel.Win32Exception){throw new InvalidOperationException("Python 3 is required. Install Python for Windows including the Python launcher, then reopen this app.");} return p;}
 void StartBuild(){ try { if(String.IsNullOrEmpty(source)){var choice=MessageBox.Show("Choose Yes for one file, or No for a folder and its subfolders.","Select source",MessageBoxButtons.YesNoCancel,MessageBoxIcon.Question); if(choice==DialogResult.Cancel)return; if(choice==DialogResult.Yes){using(var picker=new OpenFileDialog()){picker.Title="Choose a text file";picker.Filter="All files (*.*)|*.*";if(picker.ShowDialog()!=DialogResult.OK)return;source=picker.FileName;}}else{using(var picker=new FolderBrowserDialog()){picker.Description="Choose the folder containing the text files to index";if(picker.ShowDialog()!=DialogResult.OK)return;source=picker.SelectedPath;}} if(dir.StartsWith(source.TrimEnd('\\')+"\\",StringComparison.OrdinalIgnoreCase)){source="";MessageBox.Show("Choose a source folder that does not contain the app database folder.");return;} File.WriteAllText(Path.Combine(dir,"source-folder.txt"),source); } if(!Directory.Exists(source) && !File.Exists(source)){MessageBox.Show("The selected source file or folder cannot be found. Restore it before resuming.");return;} bool own; mutex=new Mutex(true,@"Local\BreachSearchBuild",out own); if(!own){mutex.Dispose();mutex=null;MessageBox.Show("A build is already running in another app window.");return;} File.Delete(Path.Combine(dir,"stop-build.flag")); worker=Run("--build"); building=true; build.Enabled=false;resume.Enabled=false;stop.Enabled=true; buildtext.Text="Starting..."; var p=worker; ThreadPool.QueueUserWorkItem(_=>{string output=p.StandardOutput.ReadToEnd(); string error=p.StandardError.ReadToEnd();p.WaitForExit(); BeginInvoke((Action)(()=>{building=false;build.Enabled=true;resume.Enabled=true;stop.Enabled=false; if(mutex!=null){mutex.ReleaseMutex();mutex.Dispose();mutex=null;} RefreshStatus(); if(p.ExitCode!=0)MessageBox.Show("Build could not finish:\n"+error,"Build error");}));}); }catch(Exception ex){if(mutex!=null){mutex.ReleaseMutex();mutex.Dispose();mutex=null;} MessageBox.Show(ex.Message,"Could not start build");}}
 void StopBuild(){try{File.WriteAllText(Path.Combine(dir,"stop-build.flag"),"");status.Text="Pausing safely; the current file may need to be retried.";stop.Enabled=false;}catch(Exception ex){MessageBox.Show(ex.Message);}}
 void RefreshStatus(){try{var d=json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(dir,"build-status.json"))); string state=Convert.ToString(d["state"]); complete=state=="Complete"; long done=d.ContainsKey("done_bytes")?Convert.ToInt64(d["done_bytes"]):0, total=d.ContainsKey("total_bytes")?Convert.ToInt64(d["total_bytes"]):0; if(total>0){double pct=100.0*done/total;progress.Value=(int)Math.Min(100,pct); buildtext.Text=state+"  |  "+pct.ToString("0.0")+"% complete";}else buildtext.Text=state; if(!building&&state=="Indexing")buildtext.Text="Not running — press Resume build"; status.Text=complete?"Build complete. Enter search text below.":"Progress counts completed source files by size. Searches are incomplete until the build finishes."; }catch{buildtext.Text=building?"Preparing...":"Ready to build";} }
 void ApplyFilter(){string f=filter.Text; int shown=0; var sb=new System.Text.StringBuilder(); foreach(string line in matches){if(line.IndexOf(f,StringComparison.OrdinalIgnoreCase)>=0){sb.AppendLine(line);shown++;}} results.Text=sb.ToString(); filterCount.Text=shown+" of "+matches.Count+" returned results shown";}
 void AddResult(string line){matches.Add(line); if(line.IndexOf(filter.Text,StringComparison.OrdinalIgnoreCase)>=0)results.AppendText(line+Environment.NewLine); if(filter.Text.Length>0)filterCount.Text="Filtering returned results..."; else filterCount.Text=matches.Count+" results shown";}
 void ExportResults(){using(var dialog=new SaveFileDialog()){dialog.Title="Save search results";dialog.Filter="Text files (*.txt)|*.txt|All files (*.*)|*.*";dialog.DefaultExt="txt";dialog.AddExtension=true;dialog.FileName="search-results.txt";if(dialog.ShowDialog()!=DialogResult.OK)return;try{int count=0;using(var writer=new StreamWriter(dialog.FileName,false,new System.Text.UTF8Encoding(false))){foreach(string line in matches){if(line.IndexOf(filter.Text,StringComparison.OrdinalIgnoreCase)>=0){writer.WriteLine(line);count++;}}}MessageBox.Show("Saved "+count+" displayed result(s).","Export complete");}catch(Exception ex){MessageBox.Show(ex.Message,"Export failed");}}}
 void StartSearch(){string term=query.Text;if(term.Length<3){MessageBox.Show("Enter at least 3 characters.");return;} if(!File.Exists(Path.Combine(dir,"search.sqlite3"))){MessageBox.Show("Start the database build first.");return;} try{searching=Run("--search"); var p=searching; p.StandardInput.WriteLine(json.Serialize(new {text=term,@case=cs.Checked}));p.StandardInput.Close();matches.Clear();results.Clear();filter.Text="";filterCount.Text="0 results shown";metric.Text="Searching...";export.Enabled=false;search.Enabled=false;cancel.Enabled=true; ThreadPool.QueueUserWorkItem(_=>{try{string line;while((line=p.StandardOutput.ReadLine())!=null){var d=json.Deserialize<Dictionary<string,object>>(line); if(d.ContainsKey("line")){string v=Convert.ToString(d["line"]);BeginInvoke((Action)(()=>AddResult(v)));}else if(d.ContainsKey("error")){string v=Convert.ToString(d["error"]);BeginInvoke((Action)(()=>metric.Text="Error: "+v));}else if(d.ContainsKey("done")){string v=d["done"]+" results in "+d["seconds"]+" seconds";BeginInvoke((Action)(()=>{metric.Text=v;ApplyFilter();}));}} string error=p.StandardError.ReadToEnd();p.WaitForExit();BeginInvoke((Action)(()=>{search.Enabled=true;cancel.Enabled=false;export.Enabled=matches.Count>0;if(p.ExitCode!=0)metric.Text=String.IsNullOrWhiteSpace(error)?"Search stopped.":error;}));}catch(Exception ex){BeginInvoke((Action)(()=>{search.Enabled=true;cancel.Enabled=false;export.Enabled=matches.Count>0;metric.Text=ex.Message;}));}}); }catch(Exception ex){search.Enabled=true;cancel.Enabled=false;MessageBox.Show(ex.Message,"Could not search");}}
 [STAThread]static void Main(){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);try{Application.Run(new App());}catch(Exception ex){MessageBox.Show(ex.ToString(),"Breach Search error");}}
}

